#include <iostream>
#include <iomanip>

int main() {
    // Part 1: Sum and sum of squares (Exercise 3.5 & 3.12)
    unsigned int x = 1;
    unsigned int sum = 0;
    unsigned int sum_of_squares = 0;

    while (x <= 10) {
        sum += x;
        unsigned int square = x * x;
        sum_of_squares += square;
        ++x;
    }

    std::cout << "Sum: " << sum << "\n";
    std::cout << "Sum of squares: " << sum_of_squares << "\n";

    // Part 2: Integer power calculation (Exercise 3.7)
    unsigned int base = 0;
    unsigned int exponent = 0;
    if (std::cin >> base >> exponent) {
        unsigned int i = 1;
        unsigned int power = 1;
        while (i <= exponent) {
            power *= base;
            ++i;
        }
        std::cout << base << "^" << exponent << " = " << power << "\n";
    }

    // Part 3: Floating point precision test (Exercise 3.3 e, f)
    double val1 = 123.4567;
    double val2 = 3.14159;
    std::cout << std::fixed << std::setprecision(2) << val1 << "\n";
    std::cout << std::fixed << std::setprecision(3) << val2 << "\n";

    return 0;
}

#include <iostream>

int main() {
    // Correcting Exercise 3.9: sum from z (10) down to 1
    int z = 10;
    int sum = 0;
    while (z >= 1) {
        sum += z;
        --z; // Crucial decrement step to prevent infinite loop
    }
    std::cout << "Sum 10 down to 1: " << sum << "\n";

    // Correcting Exercise 3.8c / 3.10a: clean if-else without trailing semicolons
    int gender = 1;
    if (gender == 1) {
        std::cout << "Woman\n";
    } else {
        std::cout << "Man\n";
    }

    // Correcting Exercise 3.10d: count down to avoid infinite loop
    int y = 5;
    std::cout << "Countdown: ";
    while (y > 0) {
        std::cout << y << " ";
        --y; // Decrement rather than incrementing ++y
    }
    std::cout << "\n";

    return 0;
}

